function hostOf(url: string): string | null {
  try {
    return new URL(/^[a-z]+:\/\//i.test(url) ? url : `https://${url}`).hostname.toLowerCase();
  } catch {
    return null;
  }
}

/** La web conocida a la que pertenece una dirección (subdominios incluidos). */
export function siteFor(url: string | null | undefined): Site | undefined {
  const host = url ? hostOf(url.trim()) : null;
  if (!host) return undefined;
  return SITES.find((s) => s.hosts.some((h) => host === h || host.endsWith(`.${h}`)));
}
